1	using Microsoft.Data.SqlClient;
2	using Microsoft.EntityFrameworkCore;
3	using seed_a_backend.Api.Domain;
4	using seed_a_backend.Api.Infrastructure;
5	
6	namespace seed_a_backend.Tests;
7	
8	/// <summary>
9	/// Verifiziert die per DB-CHECK-Constraint erzwungene Invariante, dass `BookingPosition.BookingId`
10	/// und `PriceCategoryId` immer gemeinsam null oder gemeinsam gesetzt sind (AD-2), statt sie nur
11	/// über einen XML-Doc-Kommentar zu dokumentieren.
12	/// </summary>
13	public class BookingPositionInvariantTests : IAsyncLifetime
14	{
15	    private const string CheckConstraintName = "CK_BookingPositions_BookingId_PriceCategoryId_BeideNullOderBeideGesetzt";
16	
17	    private readonly SqlServerTestDatabase _database = new();
18	
19	    public ValueTask InitializeAsync() => _database.InitializeAsync();
20	
21	    public ValueTask DisposeAsync() => _database.DisposeAsync();
22	
23	    /// <summary>
24	    /// Prüft nicht nur den Exception-Typ, sondern dass die `DbUpdateException` tatsächlich vom
25	    /// erwarteten CHECK-Constraint stammt (SQL-Server-Fehlernummer 547 für CHECK-/FK-Verletzungen,
26	    /// plus Constraint-Name in der Meldung) — sonst würde auch eine zufällige `DbUpdateException`
27	    /// aus einer anderen Ursache (z. B. FK- oder Unique-Index-Verletzung) den Test bestehen lassen.
28	    /// </summary>
29	    private static async Task AssertViolatesCheckConstraintAsync(Func<Task> saveChanges)
30	    {
31	        var ex = await Assert.ThrowsAsync<DbUpdateException>(saveChanges);
32	        var sqlException = Assert.IsType<SqlException>(ex.InnerException);
33	        Assert.Equal(547, sqlException.Number);
34	        Assert.Contains(CheckConstraintName, sqlException.Message);
35	    }
36	
37	    private static async Task<(int EventId, int PriceCategoryId, int BookingId)> SeedGraphAsync(AppDbContext db, CancellationToken ct)
38	    {
39	        var @event = new Event { Titel = "Testkonzert", Beschreibung = "Beschreibung", Zeitpunkt = DateTime.UtcNow, DauerMinuten = 90, Altersfreigabe = 0 };
40	        var room = new Room { Name = "Saal 1", RowLabels = ["A"], ColumnCount = 5, Events = [@event] };
41	        var venue = new Venue { Name = "Testhalle", Rooms = [room] };
42	        var priceCategory = new PriceCategory { Name = "Standard", Preis = 10m };
43	        @event.PriceCategories.Add(priceCategory);
44	        var booking = new Booking { Reference = "ABCD2345", Name = "Erika Musterfrau", Email = "erika@example.com" };
45	
46	        db.Venues.Add(venue);
47	        db.Bookings.Add(booking);
48	        await db.SaveChangesAsync(ct);
49	
50	        return (@event.Id, priceCategory.Id, booking.Id);
51	    }
52	
53	    [Fact]
54	    public async Task BookingId_gesetzt_ohne_PriceCategoryId_verletzt_die_Check_Constraint()
55	    {
56	        var ct = TestContext.Current.CancellationToken;
57	        await using var db = _database.CreateContext();
58	        var (eventId, _, bookingId) = await SeedGraphAsync(db, ct);
59	
60	        db.BookingPositions.Add(new BookingPosition
61	        {
62	            EventId = eventId,
63	            RowLabel = "A",
64	            ColumnNumber = 1,
65	            BookingId = bookingId,
66	            PriceCategoryId = null,
67	        });
68	
69	        await AssertViolatesCheckConstraintAsync(() => db.SaveChangesAsync(ct));
70	    }
71	
72	    [Fact]
73	    public async Task PriceCategoryId_gesetzt_ohne_BookingId_verletzt_die_Check_Constraint()
74	    {
75	        var ct = TestContext.Current.CancellationToken;
76	        await using var db = _database.CreateContext();
