     1	using Microsoft.Data.SqlClient;
     2	using Microsoft.EntityFrameworkCore;
     3	using seed_a_backend.Api.Infrastructure;
     4	
     5	namespace seed_a_backend.Tests;
     6	
     7	/// <summary>
     8	/// Erstellt für jede Testklasse eine eigene, eindeutig benannte Testdatenbank auf dem echten
     9	/// SQL Server aus ConnectionStrings__Default (Consistency Convention „Test-Engine für
    10	/// Nebenläufigkeit“ — kein EF-Core-InMemory-Provider, da gefilterte Unique-Constraints sonst
    11	/// nicht durchgesetzt würden). Schema wird über die echten EF-Core-Migrations aufgebaut, damit
    12	/// die Migration selbst mitgetestet wird.
    13	/// </summary>
    14	public sealed class SqlServerTestDatabase : IAsyncLifetime
    15	{
    16	    private readonly string _connectionString;
    17	
    18	    public SqlServerTestDatabase()
    19	    {
    20	        _connectionString = CreateIsolatedConnectionString();
    21	    }
    22	
    23	    /// <summary>
    24	    /// Baut eine eigene, per GUID benannte Connection String für eine isolierte Testdatenbank —
    25	    /// wiederverwendbar für Tests, die (anders als diese Klasse) die Datenbank nicht vorab per
    26	    /// Migration anlegen dürfen, weil genau das Anlegen selbst Teil des zu testenden Verhaltens ist.
    27	    /// </summary>
    28	    public static string CreateIsolatedConnectionString()
    29	    {
    30	        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
    31	            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");
    32	
    33	        var builder = new SqlConnectionStringBuilder(baseConnectionString)
    34	        {
    35	            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
    36	        };
    37	        return builder.ConnectionString;
    38	    }
    39	
    40	    public AppDbContext CreateContext()
    41	    {
    42	        var options = new DbContextOptionsBuilder<AppDbContext>()
    43	            .UseSqlServer(_connectionString)
    44	            .Options;
    45	        return new AppDbContext(options);
    46	    }
    47	
    48	    public async ValueTask InitializeAsync()
    49	    {
    50	        await using var db = CreateContext();
    51	        await db.Database.MigrateAsync();
    52	    }
    53	
    54	    public async ValueTask DisposeAsync()
    55	    {
    56	        await using var db = CreateContext();
    57	        await db.Database.EnsureDeletedAsync();
    58	    }
    59	}
